"""Tests for tasks_api.queries — TaskQuery, apply_query, filtering, sorting, pagination."""

from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="t", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, created_at=None, tags=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at,
        created_at=created_at or datetime(2025, 1, id, tzinfo=timezone.utc),
        tags=tags or [],
    )


# ── TaskQuery validation ────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    def test_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=0)

    def test_limit_over_100(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=101)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  FOO  ")
        assert q.tag == "foo"

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.descending is False
        assert q.limit == 20
        assert q.offset == 0


# ── Filtering ────────────────────────────────────────────────────────────

class TestApplyQueryFilter:
    @pytest.fixture()
    def tasks(self):
        return [
            _task(1, "Buy groceries", status=TaskStatus.PENDING,
                  tags=[Tag("shopping")]),
            _task(2, "Write report", status=TaskStatus.DONE),
            _task(3, "Call dentist", status=TaskStatus.PENDING,
                  due_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),  # overdue
        ]

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert len(page.items) == 2

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert [t.id for t in page.items] == [1]

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="call"), NOW)
        assert [t.id for t in page.items] == [3]

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert [t.id for t in page.items] == [3]

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 3 not in ids
        assert 1 in ids

    def test_no_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3


# ── Sorting ──────────────────────────────────────────────────────────────

class TestApplyQuerySort:
    def test_sort_by_title(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_desc(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Cherry", "Banana", "Apple"]

    def test_sort_by_priority(self):
        tasks = [
            _task(1, priority=TaskPriority.LOW),
            _task(2, priority=TaskPriority.HIGH),
            _task(3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW,
        ]

    def test_sort_by_created_at(self):
        tasks = [
            _task(1, created_at=datetime(2025, 3, 1, tzinfo=timezone.utc)),
            _task(2, created_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
        ]
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            _task(1, due_at=None),
            _task(2, due_at=datetime(2025, 3, 1, tzinfo=timezone.utc)),
            _task(3, due_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]


# ── Pagination ───────────────────────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture()
    def tasks(self):
        return [_task(i, created_at=datetime(2025, 1, i, tzinfo=timezone.utc))
                for i in range(1, 11)]

    def test_first_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=0), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_last_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=9), NOW)
        assert len(page.items) == 1
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert page.items == []
        assert page.has_more is False

    def test_exact_boundary(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=5), NOW)
        assert len(page.items) == 5
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository, normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture()
    def repo(self):
        return InMemoryTaskRepository()

    def test_add_and_get(self, repo):
        t = make_task(id=1)
        repo.add(t)
        assert repo.get(1) is t

    def test_get_missing(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        result = repo.list()
        assert isinstance(result, list)
        assert len(result) == 2

    def test_update(self, repo):
        repo.add(make_task(id=1, title="old"))
        updated = make_task(id=1, title="new")
        repo.update(updated)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        names = [t.name for t in result]
        assert names == ["foo", "bar"]

    def test_strings_converted(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed(self):
        result = normalize_tags([Tag("a"), "A", "b"])
        assert [t.name for t in result] == ["a", "b"]

    def test_empty(self):
        assert normalize_tags([]) == []

