from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── TaskStatus / TaskPriority enums ──────────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


# ── Tag ──────────────────────────────────────────────────────────────────

class TestTag:
    def test_normalizes_case_and_whitespace(self):
        assert Tag("  FOO  ").name == "foo"

    def test_allows_letters_digits_hyphen_underscore(self):
        t = Tag("my-tag_1")
        assert t.name == "my-tag_1"

    def test_rejects_non_string_name(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)

    def test_rejects_empty_name(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_rejects_illegal_character(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("bad tag!")


# ── Task.is_overdue ──────────────────────────────────────────────────────

class TestTaskIsOverdue:
    def test_not_overdue_when_no_due_date(self):
        t = Task(id=1, title="x")
        assert t.is_overdue(datetime.now(timezone.utc)) is False

    def test_not_overdue_when_done(self):
        t = Task(
            id=1, title="x", status=TaskStatus.DONE,
            due_at=datetime(2020, 1, 1, tzinfo=timezone.utc),
        )
        assert t.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is False

    def test_overdue_when_past_due(self):
        t = Task(
            id=1, title="x",
            due_at=datetime(2025, 1, 1, tzinfo=timezone.utc),
        )
        assert t.is_overdue(datetime(2025, 6, 1, tzinfo=timezone.utc)) is True

    def test_not_overdue_when_future_due(self):
        t = Task(
            id=1, title="x",
            due_at=datetime(2030, 1, 1, tzinfo=timezone.utc),
        )
        assert t.is_overdue(datetime(2025, 6, 1, tzinfo=timezone.utc)) is False

"""Tests for tasks_api.repository — InMemoryTaskRepository, normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture()
    def repo(self):
        return InMemoryTaskRepository()

    def test_add_and_get(self, repo):
        t = make_task(id=1)
        repo.add(t)
        assert repo.get(1) is t

    def test_get_missing(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        result = repo.list()
        assert isinstance(result, list)
        assert len(result) == 2

    def test_update(self, repo):
        repo.add(make_task(id=1, title="old"))
        updated = make_task(id=1, title="new")
        repo.update(updated)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        names = [t.name for t in result]
        assert names == ["foo", "bar"]

    def test_strings_converted(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed(self):
        result = normalize_tags([Tag("a"), "A", "b"])
        assert [t.name for t in result] == ["a", "b"]

    def test_empty(self):
        assert normalize_tags([]) == []
